// Headless Chrome + raw CDP, no deps. Usage: node drive.mjs <url> <outdir>
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";

const [url, outdir] = process.argv.slice(2);
mkdirSync(outdir, { recursive: true });
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const port = 9333;
const chrome = spawn(CHROME, [
  "--headless=new", "--disable-gpu", "--no-first-run", "--hide-scrollbars",
  "--window-size=1400,900", `--remote-debugging-port=${port}`,
  `--user-data-dir=${outdir}/profile`, "about:blank",
], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const die = (msg) => { console.error("FAIL:", msg); chrome.kill(); process.exit(1); };

let version;
for (let i = 0; i < 60 && !version; i++) {
  try { version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json(); } catch { await sleep(250); }
}
if (!version) die("chrome did not start");
const target = await (await fetch(`http://127.0.0.1:${port}/json/new`, { method: "PUT" })).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let seq = 0; const pending = new Map(); const errors = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id) { pending.get(m.id)?.(m); pending.delete(m.id); return; }
  if (m.method === "Runtime.exceptionThrown") errors.push("exception: " + (m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text));
  if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error") errors.push("console.error: " + m.params.args.map((a) => a.value ?? a.description).join(" ").slice(0, 300));
  if (m.method === "Log.entryAdded" && m.params.entry.level === "error") errors.push("log: " + m.params.entry.text + " " + (m.params.entry.url ?? ""));
};
const send = (method, params = {}) => new Promise((res, rej) => {
  const id = ++seq; pending.set(id, (m) => (m.error ? rej(new Error(method + ": " + m.error.message)) : res(m.result)));
  ws.send(JSON.stringify({ id, method, params }));
});
const evaluate = async (expression) => {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);
  return r.result.value;
};
const waitFor = async (expression, ms = 30000) => {
  const start = Date.now();
  while (Date.now() - start < ms) { if (await evaluate(expression)) return; await sleep(250); }
  die("timeout waiting for: " + expression);
};
let n = 0;
const shot = async (name) => {
  const { data } = await send("Page.captureScreenshot", { format: "png" });
  const file = `${outdir}/${String(++n).padStart(2, "0")}-${name}.png`;
  writeFileSync(file, Buffer.from(data, "base64"));
  console.log("  screenshot", file);
};
const setSelect = (selector, value) => evaluate(`(() => {
  const el = document.querySelector(${JSON.stringify(selector)});
  Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value").set.call(el, ${JSON.stringify(value)});
  el.dispatchEvent(new Event("change", { bubbles: true }));
  return el.value;
})()`);
const clickButton = (pattern) => evaluate(`(() => {
  const b = [...document.querySelectorAll("button")].find((b) => ${pattern}.test(b.textContent.trim()));
  if (!b) throw new Error("no button matching ${pattern}");
  b.click(); return b.textContent.trim();
})()`);
const EDITOR = `!!document.querySelector('#doc-language') && !!document.querySelector('.cm-content')`;
const REVIEWING = `document.querySelectorAll('button[name="accept"]').length > 0`;
const pill = () => evaluate(`document.querySelector('[class*="rounded-full"]')?.textContent`);
const firstLine = () => evaluate(`document.querySelector('.cm-line')?.textContent`);

await send("Page.enable"); await send("Runtime.enable"); await send("Log.enable");
await send("Page.navigate", { url });

console.log("1. load");
await waitFor(EDITOR);
console.log("  readyState:", await evaluate("document.readyState"), "| title:", await evaluate("document.title"), "| lang:", await evaluate("document.documentElement.lang"));
console.log("  first line:", await firstLine());
await shot("loaded");

console.log("2. text language -> pt-BR (translate)");
await setSelect("#doc-language", "pt-BR");
await sleep(150);
console.log("  while loading, pill:", await pill(), "| select disabled:", await evaluate(`document.querySelector('#doc-language').disabled`));
await waitFor(REVIEWING);
console.log("  reviewing, pill:", await pill(), "| chunks:", await evaluate(`document.querySelectorAll('button[name="accept"]').length`));
await shot("translate-review");

console.log("3. accept all");
console.log("  clicked:", await clickButton(`/^(Accept all|Aceitar tudo|Aceptar todo|全部接受)$/`));
await waitFor(`document.querySelectorAll('button[name="accept"]').length === 0`);
console.log("  doc language:", await evaluate(`document.querySelector('#doc-language').value`), "| first line:", await firstLine());
await shot("translated");

console.log("4. reload (persistence)");
await send("Page.reload");
await sleep(500);
await waitFor(EDITOR);
console.log("  doc language:", await evaluate(`document.querySelector('#doc-language').value`), "| first line:", await firstLine());
console.log("  localStorage:", await evaluate(`JSON.stringify(Object.fromEntries(Object.keys(localStorage).filter(k=>k!=='coauthor.doc').map(k=>[k, localStorage.getItem(k)])))`));
await shot("reloaded");

console.log("5. interface language -> zh-CN");
await setSelect("header select", "zh-CN");
await waitFor(`document.title === '合著者'`);
console.log("  title:", await evaluate("document.title"), "| lang:", await evaluate("document.documentElement.lang"), "| pill:", await pill());
console.log("  quick actions:", await evaluate(`[...document.querySelectorAll('button')].map(b=>b.textContent.trim()).filter(Boolean).join(' / ')`));
await shot("zh-ui");

console.log("6. quick action on whole document, then reject all");
console.log("  clicked:", await clickButton(`/^(改进|Improve|Melhorar|Mejorar)$/`));
await waitFor(REVIEWING);
console.log("  pill:", await pill(), "| per-chunk buttons:", await evaluate(`[...document.querySelectorAll('button[name]')].map(b=>b.textContent).join('/')`));
await shot("improve-review");
console.log("  clicked:", await clickButton(`/^(全部拒绝|Reject all|Rejeitar tudo|Rechazar todo)$/`));
await waitFor(`document.querySelectorAll('button[name="accept"]').length === 0`);
console.log("  pill:", await pill());

console.log("console errors:", errors.length ? "\n  " + errors.join("\n  ") : "none");
ws.close(); chrome.kill();
EOF
