  b.click(); return b.textContent.trim();
})()`);
const EDITOR = `!!document.querySelector('#doc-language') && !!document.querySelector('.cm-content')`;
const REVIEWING = `document.querySelectorAll('button[name="accept"]').length > 0`;
const pill = () => evaluate(`document.querySelector('[class*="rounded-full"]')?.textContent`);
const firstLine = () => evaluate(`document.querySelector('.cm-line')?.textContent`);

