await waitFor(EDITOR);
console.log("  readyState:", await evaluate("document.readyState"), "| title:", await evaluate("document.title"), "| lang:", await evaluate("document.documentElement.lang"));
console.log("  first line:", await firstLine());
await shot("loaded");

console.log("2. text language -> pt-BR (translate)");
await setSelect("#doc-language", "pt-BR");
await sleep(150);
console.log("  while loading, pill:", await pill(), "| select disabled:", await evaluate(`document.querySelector('#doc-language').disabled`));
await waitFor(REVIEWING);
console.log("  reviewing, pill:", await pill(), "| chunks:", await evaluate(`document.querySelectorAll('button[name="accept"]').length`));
await shot("translate-review");

console.log("3. accept all");
console.log("  clicked:", await clickButton(`/^(Accept all|Aceitar tudo|Aceptar todo|全部接受)$/`));
await waitFor(`document.querySelectorAll('button[name="accept"]').length === 0`);
console.log("  doc language:", await evaluate(`document.querySelector('#doc-language').value`), "| first line:", await firstLine());
await shot("translated");

console.log("4. reload (persistence)");
await send("Page.reload");
await sleep(500);
await waitFor(EDITOR);
console.log("  doc language:", await evaluate(`document.querySelector('#doc-language').value`), "| first line:", await firstLine());
console.log("  localStorage:", await evaluate(`JSON.stringify(Object.fromEntries(Object.keys(localStorage).filter(k=>k!=='coauthor.doc').map(k=>[k, localStorage.getItem(k)])))`));
await shot("reloaded");

console.log("5. interface language -> zh-CN");
await setSelect("header select", "zh-CN");
await waitFor(`document.title === '合著者'`);
console.log("  title:", await evaluate("document.title"), "| lang:", await evaluate("document.documentElement.lang"), "| pill:", await pill());
console.log("  quick actions:", await evaluate(`[...document.querySelectorAll('button')].map(b=>b.textContent.trim()).filter(Boolean).join(' / ')`));
await shot("zh-ui");

console.log("6. quick action on whole document, then reject all");
console.log("  clicked:", await clickButton(`/^(改进|Improve|Melhorar|Mejorar)$/`));
await waitFor(REVIEWING);
console.log("  pill:", await pill(), "| per-chunk buttons:", await evaluate(`[...document.querySelectorAll('button[name]')].map(b=>b.textContent).join('/')`));
await shot("improve-review");
console.log("  clicked:", await clickButton(`/^(全部拒绝|Reject all|Rejeitar tudo|Rechazar todo)$/`));
await waitFor(`document.querySelectorAll('button[name="accept"]').length === 0`);
console.log("  pill:", await pill());

console.log("console errors:", errors.length ? "\n  " + errors.join("\n  ") : "none");
ws.close(); chrome.kill();
EOF
