    41	
    42	function noticeText(notice: Notice, copy: Messages): string | null {
    43	  if (!notice) return null;
    44	  if (notice.kind === "nothing") return copy.nothing;
    45	  if (notice.kind === "generic") return copy.generic;
    46	  if (notice.error === "document_too_long") return notice.translating ? copy.translationTooLong : copy.documentTooLong;
    47	  if (notice.error === "missing_key") return copy.missingKey;
    48	  if (notice.error === "budget_exhausted") return copy.budgetExhausted(`$${(notice.remaining ?? 0).toFixed(2)}`);
    49	  if (notice.error === "invalid_request") return copy.invalidRequest;
    50	  if (notice.error === "upstream_error") return copy.upstreamError;
    51	  return copy.requestFailed(notice.status);
