  const flushOnHide = () => {
    const update = take();
    if (!update) return;
    void fetch(`${SUPABASE_URL}/rest/v1/${TABLE}`, {
      method: "POST",
      keepalive: true,
      headers: {
        apikey: SUPABASE_KEY!,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
