rep(`  getDoc(): string;
  /** Review editor: show \`text\` as tracked changes replacing \`range\`. Returns the number of changed chunks. */
  propose(range: Range, text: string): number;
`, `  getDoc(): string;
`);
rep(`  /** Review editor: the snapshot to review. */
  initialDoc?: string;
`, `  /** Review editor: the snapshot to review. */
  initialDoc?: string;
  /** Review editor: shown as tracked changes over the snapshot. A new object starts a new round from the snapshot. */
  proposal?: { range: Range; text: string };
`);
rep(`export default function Editor({ ref, collab, initialDoc = "", chunkLabels, onChange, onSelectionChange, onChunks }: Props) {`,
    `export default function Editor({ ref, collab, initialDoc = "", proposal, chunkLabels, onChange, onSelectionChange, onChunks }: Props) {`);
rep(`  function resolve(anchors: Anchors) {`, `  // Each new proposal (first one, or a refine) starts again from the untouched snapshot.
  useEffect(() => {
    const v = view.current;
    if (!v || !proposal) return;
    reviewing.current = false;
    v.dispatch({
      effects: merge.current.reconfigure(unifiedMergeView({ original: initialDoc, allowInlineDiffs: true })),
      changes: [
        { from: 0, to: v.state.doc.length, insert: initialDoc },
      ],
    });
    v.dispatch({
      changes: { from: proposal.range.from, to: proposal.range.to, insert: proposal.text },
      selection: { anchor: proposal.range.from },
      scrollIntoView: true,
    });
    const count = getChunks(v.state)?.chunks.length ?? 0;
    lastCount.current = count;
    callbacks.current.onChunks?.(count);
    if (count === 0) endReview(v);
    else reviewing.current = true;
    // initialDoc is fixed for a review editor's lifetime.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [proposal]);

  function resolve(anchors: Anchors) {`);
// drop the imperative propose
s = s.replace(/    propose\(range, text\) \{[\s\S]*?\n    \},\n    acceptAll\(\) \{/, `    acceptAll() {`);
// endReview may run after the review editor unmounted
rep(`                if (count === 0) queueMicrotask(() => endReview(v));`, `                if (count === 0) queueMicrotask(() => { if (view.current === v) endReview(v); });`);
rep(`    return () => v.destroy();`, `    return () => {
      view.current = null;
      v.destroy();
    };`);
fs.writeFileSync(p, s);
console.log("ok", s.includes("propose(range, text)") ? "STILL HAS propose" : "propose removed");
