// Minimal headless Chrome over CDP, no deps. Exports helpers for test scripts.
import { spawn } from "node:child_process";
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
export async function launch(dir, port = 9335) {
  const chrome = spawn("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", ["--headless=new", "--disable-gpu", "--no-first-run", "--lang=en-US", "--window-size=1400,900", `--remote-debugging-port=${port}`, `--user-data-dir=${dir}/profile-${port}`, "about:blank"], { stdio: "ignore" });
  let v; for (let i = 0; i < 80 && !v; i++) { try { v = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json(); } catch { await sleep(250); } }
  async function tab() {
    const t = await (await fetch(`http://127.0.0.1:${port}/json/new`, { method: "PUT" })).json();
    const ws = new WebSocket(t.webSocketDebuggerUrl); await new Promise((r) => (ws.onopen = r));
    let id = 0; const p = new Map(); const errors = [];
    ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id) { p.get(m.id)?.(m); p.delete(m.id); } else if (m.method === "Runtime.exceptionThrown") errors.push(m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text); else if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error") errors.push(m.params.args.map((a) => a.value ?? a.description).join(" ")); };
    const send = (method, params = {}) => new Promise((r) => { p.set(++id, r); ws.send(JSON.stringify({ id, method, params })); });
    const ev = async (expression) => { const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true }); if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description ?? "eval failed"); return r.result.result.value; };
    const waitFor = async (expr, ms = 20000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await ev(expr)) return; await sleep(200); } throw new Error("timeout: " + expr); };
    await send("Runtime.enable"); await send("Page.enable");
    return { send, ev, waitFor, errors, nav: (url) => send("Page.navigate", { url }), type: (text) => send("Input.insertText", { text }), close: () => ws.close() };
  }
  return { tab, kill: () => chrome.kill() };
}
// Page helpers (strings evaluated in the page)
export const SHARED = `document.querySelector('.cm-content')`;
export const sharedText = `[...${SHARED}.querySelectorAll('.cm-line')].map(l => l.textContent).join('\\n')`;
export const firstLine = `${SHARED}.querySelector('.cm-line').textContent`;
export const reviewOpen = `!!document.querySelector('[data-testid=review] .cm-content')`;
export const notice = `[...document.querySelectorAll('p,div,span')].map(e => e.childElementCount === 0 ? e.textContent : '').find(t => /changed|alterou|cambió|修改|nothing|nada/i.test(t)) ?? null`;
export const click = (re) => `(() => { const b = [...document.querySelectorAll('button')].find((b) => ${re}.test(b.textContent.trim())); if (!b) throw new Error('no button ' + ${JSON.stringify(String(re))}); b.click(); return b.textContent.trim(); })()`;
export const setSelect = (sel, v) => `(() => { const el = document.querySelector(${JSON.stringify(sel)}); Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, ${JSON.stringify(v)}); el.dispatchEvent(new Event('change', { bubbles: true })); return el.value; })()`;
export const focusEnd = `(() => { const l = [...${SHARED}.querySelectorAll('.cm-line')].at(-1); const r = document.createRange(); r.selectNodeContents(l); r.collapse(false); const s = getSelection(); s.removeAllRanges(); s.addRange(r); ${SHARED}.focus(); })()`;
EOF
