import { launch, sleep, sharedText, reviewOpen, click } from "./cdp.mjs";
const b = await launch(process.argv[2], 9340); const t = await b.tab();
const ok = (c, m) => console.log((c ? "PASS " : "FAIL ") + m);
const reviewText = `[...document.querySelectorAll('[data-testid=review] .cm-line')].map(l => l.textContent).join('\\n')`;
try {
  await t.nav("http://localhost:3125/"); await t.waitFor(`!!document.querySelector(".cm-content")`); await t.ev(`localStorage.setItem("coauthor.locale", "en-US")`);
  await t.nav("http://localhost:3125/"); await t.waitFor(`location.pathname.startsWith("/d/")`); await t.waitFor(`!!document.querySelector(".cm-content")`);
  const before = await t.ev(sharedText);
  await t.ev(click(/^Improve$/)); await t.waitFor(reviewOpen);
  const first = await t.ev(reviewText);
  // Refine: type into the bar's input (React-controlled) and submit.
  await t.ev(`document.querySelector('form input').focus()`); await t.send("Input.insertText", { text: "Make it shorter" });
  await t.ev(click(/^Refine$/)); await sleep(1200); await t.waitFor(reviewOpen);
  const second = await t.ev(reviewText);
  ok(second !== first, "refine replaces the proposal in the review");
  ok((await t.ev(sharedText)) === before, "shared text still unchanged after refine");
  await t.ev(click(/^Accept all$/)); await t.waitFor(`!(${reviewOpen})`);
  ok((await t.ev(sharedText)) === second, "accept applies the refined proposal");
  console.log("page errors:", t.errors.length ? t.errors : "none");
} catch (e) { console.log("ERROR", e.message); } finally { t.close(); b.kill(); }
EOF
node --experimental-websocket --no-warnings refine.mjs $T

