T=/var/folders/1g/r_hg1ptn4jd61_ng4l37x8880000gn/T/tmp.pBDmpMP5IU && npx next build > $T/b.log 2>&1 && echo "build ok" && (MOCK_AI=1 nohup npx next start -p 3125 > $T/start.log 2>&1 &) && curl -s --retry 20 --retry-delay 1 --retry-connrefused --retry-all-errors -o /dev/null -w "mock+supabase :3125 -> %{http_code}\n" http://localhost:3125/ && cd $T && cat > two.mjs <<'EOF'
import { launch, sleep, sharedText, firstLine, reviewOpen, notice, click, setSelect, clickInsideText } from "./cdp.mjs";
const [base, dir] = process.argv.slice(2);
const b = await launch(dir, 9341);
const ok = (c, m) => console.log((c ? "PASS " : "FAIL ") + m);
const presence = `document.querySelector('[data-testid=presence]').textContent`;
const until = async (t, expr, ms = 10000) => { try { await t.waitFor(expr, ms); return true; } catch { return false; } };
const A = await b.tab(), B = await b.tab();
try {
  await A.nav(base + "/"); await A.waitFor(`!!document.querySelector(".cm-content")`); await A.ev(`localStorage.setItem("coauthor.locale", "en-US")`);
  await A.nav(base + "/"); await A.waitFor(`location.pathname.startsWith("/d/")`); await A.waitFor(`!!document.querySelector(".cm-content")`);
  const url = base + (await A.ev("location.pathname"));
  console.log("  doc:", url);
  await sleep(1500); // let the seed save
  await B.nav(url); await B.waitFor(`!!document.querySelector(".cm-content")`);
  ok(await until(B, `${firstLine} === "# Launch plan for the new onboarding flow"`), "B opens the same document with the seeded text");
  ok(await until(A, `/2 people/.test(${presence})`) && await until(B, `/2 people/.test(${presence})`), "both tabs show 2 people editing");

  // Live typing
  await clickInsideText(A); await A.type("LIVE ");
  ok(await until(B, `(${sharedText}).includes("LIVE ")`), "A's typing appears in B");
  ok(await until(B, `!!document.querySelector('.cm-ySelectionInfo')`), "B shows A's cursor label: " + await B.ev(`document.querySelector('.cm-ySelectionInfo')?.textContent ?? ''`));

  // Private review, then apply
  const beforeB = await B.ev(sharedText);
  await A.ev(click(/^Improve$/)); await A.waitFor(reviewOpen);
  await sleep(800);
  ok((await B.ev(sharedText)) === beforeB, "B sees nothing while A reviews the suggestion");
  await A.ev(click(/^Accept all$/)); await A.waitFor(`!(${reviewOpen})`);
  ok(await until(B, `!(${sharedText}).includes("very rough")`), "B receives the accepted suggestion");
  const synced = (await A.ev(sharedText)) === (await B.ev(sharedText));
  ok(synced, "A and B have identical text");

  // Conflict at apply time: B edits the target while A reviews
  await A.ev(click(/^Improve$/)); await A.waitFor(reviewOpen);
  await clickInsideText(B); await B.type("BEDIT ");
  await until(A, `(${sharedText}).includes("BEDIT ")`);
  await A.ev(click(/^Accept all$/)); await A.waitFor(`!(${reviewOpen})`);
  ok(/changed/i.test((await A.ev(notice)) ?? ""), "A's accept is refused: " + (await A.ev(notice)));
  ok((await B.ev(sharedText)).includes("BEDIT ") && (await A.ev(sharedText)).includes("BEDIT "), "B's edit survives in both tabs");

  // Shared document language
  await A.ev(setSelect("#doc-language", "pt-BR")); await A.waitFor(reviewOpen);
  await A.ev(click(/^Accept all$/)); await A.waitFor(`!(${reviewOpen})`);
  ok(await until(B, `document.querySelector('#doc-language').value === "pt-BR"`), "B's text language switches to pt-BR");
  ok(await until(B, `${firstLine}.startsWith("# Plano")`), "B gets the translated text");
  const finalText = await A.ev(sharedText);

  // Persistence: close everything, open fresh
  await sleep(1500);
  A.close(); B.close();
  await sleep(500);
  const C = await b.tab();
  await C.nav(url); await C.waitFor(`!!document.querySelector(".cm-content")`);
  ok(await until(C, `${firstLine}.startsWith("# Plano")`), "a fresh tab loads the saved text");
  ok((await C.ev(sharedText)) === finalText, "saved text matches exactly");
  ok((await C.ev(`document.querySelector('#doc-language').value`)) === "pt-BR", "saved document language is pt-BR");
  console.log("page errors:", [...A.errors, ...B.errors, ...C.errors].length ? [...A.errors, ...B.errors, ...C.errors] : "none");
  C.close();
} catch (e) { console.log("ERROR", e.message, A.errors, B.errors); }
finally { b.kill(); }
EOF
node --experimental-websocket --no-warnings two.mjs http://localhost:3125 $T

