import { launch, sleep, sharedText, click, reviewOpen, clickInsideText } from "./cdp.mjs";
const [base, dir] = process.argv.slice(2);
const ok = (c, m) => console.log((c ? "PASS " : "FAIL ") + m);
// Session 1: create a doc, type, accept an AI edit, then kill the whole browser.
const b1 = await launch(dir, 9344); const A = await b1.tab();
await A.nav(base + "/"); await A.waitFor(`!!document.querySelector(".cm-content")`); await A.ev(`localStorage.setItem("coauthor.locale", "en-US")`);
await A.nav(base + "/"); await A.waitFor(`location.pathname.startsWith("/d/")`); await A.waitFor(`!!document.querySelector(".cm-content")`);
const url = base + (await A.ev("location.pathname"));
await clickInsideText(A); await A.type("SAVED ");
await A.ev(click(/^Improve$/)); await A.waitFor(reviewOpen); await A.ev(click(/^Accept all$/)); await A.waitFor(`!(${reviewOpen})`);
await clickInsideText(A); await A.type("LAST ");
const finalText = await A.ev(sharedText);
await sleep(1200); // > FLUSH_MS
b1.kill(); await sleep(1500);
// Session 2: a brand-new browser profile, nobody else online.
const b2 = await launch(dir + "/second", 9345); const C = await b2.tab();
await C.nav(url); await C.waitFor(`!!document.querySelector(".cm-content")`); await sleep(800);
const saved = await C.ev(sharedText);
ok(saved === finalText, `fresh browser loads exactly the saved text (${saved.length} chars)`);
ok(saved.includes("SAVED ") && saved.includes("LAST ") && !saved.includes("very rough"), "typing and the accepted AI edit were both saved");
console.log("  presence:", await C.ev(`document.querySelector('[data-testid=presence]').textContent`));
console.log("  doc id:", url.split("/d/")[1]);
C.close(); b2.kill();
EOF
node --experimental-websocket --no-warnings persist.mjs http://localhost:3125 $T

